const d = dealer.dealer_account_information ?? {};
const address = [d.store_address, d.store_city, d.store_state, d.store_postal, d.store_country].filter(Boolean).join(', ');
const weekly = d.weekly_availability ?? {};
const dayNames = {monday:'Monday',tuesday:'Tuesday',wednesday:'Wednesday',thursday:'Thursday',friday:'Friday',saturday:'Saturday',sunday:'Sunday'};
const hours = Object.entries(weekly).filter(([,v]) => v?.active && v.start && v.end).map(([k,v]) => ({ day: dayNames[k] ?? k, start: v.start, end: v.end }));
envelope.context.dealer = { ...(envelope.context.dealer ?? {}), id: envelope.identity.dealer_id, bot_name: d.ai_bot_name ?? envelope.context.dealer?.bot_name ?? null, store_name: d.store_name ?? envelope.context.dealer?.store_name ?? null, store_phone: d.alternative_contact_number ?? envelope.context.dealer?.store_phone ?? envelope.event.recipient, sms_conversion_phone: d.sms_conversion_phone ?? envelope.event.recipient, store_address: address || envelope.context.dealer?.store_address || null, timezone: d.time_zone ?? null, store_website: d.store_website ?? envelope.context.dealer?.store_website ?? null, manager_name: d.general_manager ?? envelope.context.dealer?.manager_name ?? null, trade_url: d.trade_in_appraisal_url ?? envelope.context.dealer?.trade_url ?? null, finance_url: d.credit_finance_application_url ?? envelope.context.dealer?.finance_url ?? null, booking_url: envelope.identity.dealer_id && envelope.identity.lead_id ? `https://www.autopulse.ai/booking/${envelope.identity.dealer_id}/${envelope.identity.lead_id}` : null, store_hours: hours, store_hours_text: hours.length ? hours.map(h => `${h.day}: ${h.start}–${h.end}`).join(', ') : 'No available store hours at the moment.' };
envelope.context.current_time = { iso: new Date().toISOString(), timezone: envelope.context.dealer.timezone };
return [{json:envelope}];

const envelope = JSON.parse(JSON.stringify($node['Structure Dealer Context'].json));
const truthy = v => v === true || v === 1 || v === '1' || String(v).toLowerCase() === 'true';
const id=v=>v?.$oid?String(v.$oid):v===undefined||v===null?null:String(v);
const timeOf=r=>{const value=r.timestamp??r.date??r.created_at??r.createdAt;const ms=Date.parse(value);return Number.isFinite(ms)?ms:null;};
const rawCutoff=envelope.event.received_at;const cutoff=Date.parse(rawCutoff);const hasCutoff=!!rawCutoff&&Number.isFinite(cutoff);
const warnings=envelope.context.resolution.warnings??(envelope.context.resolution.warnings=[]);
if(!hasCutoff&&!warnings.includes('MISSING_OR_INVALID_EVENT_RECEIVED_AT_NO_HISTORY_CUTOFF'))warnings.push('MISSING_OR_INVALID_EVENT_RECEIVED_AT_NO_HISTORY_CUTOFF');
const rows = $input.all().map(i=>i.json).filter(r=>r && Object.keys(r).length && (r._id || r.message_id));
const currentId=id(envelope.event.message_id);
const historical=rows.filter(r=>id(r.message_id)!==currentId&&(!hasCutoff||(timeOf(r)!==null&&timeOf(r)<=cutoff)));
if(hasCutoff&&rows.some(r=>id(r.message_id)!==currentId&&timeOf(r)===null)&&!warnings.includes('HISTORY_RECORD_WITHOUT_VALID_TIMESTAMP_EXCLUDED'))warnings.push('HISTORY_RECORD_WITHOUT_VALID_TIMESTAMP_EXCLUDED');
historical.sort((a,b)=>{const byTime=(timeOf(a)??0)-(timeOf(b)??0);if(byTime)return byTime;return String(id(a._id)??id(a.message_id)??'').localeCompare(String(id(b._id)??id(b.message_id)??''));});
const allowed = historical.filter(r => !truthy(r.internal_use) && (r.use_replies_for_ai === undefined || r.use_replies_for_ai === null || truthy(r.use_replies_for_ai)));
const isNote = r => truthy(r.is_note ?? r.isNote)||String(r.communication_type??'').toLowerCase()==='note';
envelope.context.sms_history = allowed.filter(r => !isNote(r) && String(r.communication_type ?? 'sms').toLowerCase() !== 'email').map(r => ({ direction: ['received','incoming'].includes(String(r.status).toLowerCase()) ? 'inbound' : 'outbound', content: r.mail_content ?? r.message ?? r.content ?? r.api_response?.Response ?? null, status: r.status ?? null, timestamp: r.timestamp ?? r.date ?? r.created_at ?? r.createdAt ?? null, message_id: r.message_id ? String(r.message_id) : null })).filter(r=>r.content);
envelope.context.lead_notes = allowed.filter(isNote).map(r => ({ text: r.note ?? r.note_content ?? r.noteText ?? r.mail_content ?? r.message ?? null, timestamp: r.timestamp ?? r.date ?? r.created_at ?? r.createdAt ?? null })).filter(r=>r.text);
return [{json:envelope}];

