const attachments = $json.event.attachments ?? [];
if (!attachments.length) return [{json:{route:'UNSUPPORTED',modality:'none',filename:null,content_type:null,url:null,source_index:-1,analysis_status:'no_attachment'}}];
return attachments.map((a,index)=>{
  const name=String(a.filename??'').toLowerCase();
  const type=String(a.content_type??a.contentType??'').toLowerCase();
  let route='UNSUPPORTED';
  if(type.startsWith('image/')||/\.(jpg|jpeg|png|webp|gif)$/.test(name)) route='IMAGE';
  else if(type.startsWith('video/')||/\.(mp4|mov|avi|mkv)$/.test(name)) route='VIDEO';
  else if(type==='application/pdf'||/\.pdf$/.test(name)) route='PDF';
  else if(type.startsWith('text/')||/\.(txt|csv)$/.test(name)) route='TEXT';
  return {json:{...a,content_type:type,source_index:a.source_index??index,route}};
});
